  async function deleteWorkshopPair(registration) {
    if (readOnly) { alert("Dieser Admin-Zugang ist nur zum Lesen freigegeben."); return; }
    if (!registration?.id || deletingWorkshopPairId) return;
    const name1 = registration.user1_name || "Person 1";
    const name2 = registration.user2_name || "Person 2";
    const workshopTitle = registration.workshop?.title || "diesem Workshop";
    if (!window.confirm(`Möchtest du das Tanzpaar ${name1} + ${name2} wirklich von „${workshopTitle}“ abmelden?\n\nDer Paarplatz wird danach wieder frei.`)) return;
    setDeletingWorkshopPairId(String(registration.id));
    try {
      const { error } = await supabase.rpc("admin_delete_workshop_pair", { p_registration_id: registration.id });
      if (error) throw new Error(error.message);
      alert("Das Tanzpaar wurde erfolgreich abgemeldet. 🗑️");
      setExpandedWorkshopPairs(prev => { const next = { ...prev }; delete next[String(registration.id)]; return next; });
      await loadWorkshopRegistrations();
    } catch (error) {
      console.error("Fehler beim Löschen der Workshop-Paaranmeldung:", error);
      alert(error.message || "Das Tanzpaar konnte nicht abgemeldet werden.");
    } finally { setDeletingWorkshopPairId(""); }
  }

