  async function updateContactRequest(id, status) {
    if (readOnly) {
      alert("Dieser Admin-Zugang ist nur zum Lesen freigegeben.");
      return;
    }
    // Vorherigen Status merken, damit eine Bestätigungs-Mail
    // nicht mehrfach verschickt wird, wenn der Admin eine bereits
    // angenommene Anfrage erneut speichert.
    const existingRequest = contactRequests.find(
      request => request.id === id
    );
    const wasAlreadyAccepted =
      existingRequest?.status === "accepted";

    const { error } = await supabase
      .from("contact_requests")
      .update({
        status,
        updated_at: new Date().toISOString()
      })
      .eq("id", id);

    if (error) {
      alert(
        "Fehler beim Ändern der Kontaktanfrage: " +
          error.message
      );
      return;
    }

    // Auch bei einer Annahme über den Admin-Bereich bekommt
    // der Anfragende direkt die Bestätigungs-Mail.
    if (
      status === "accepted" &&
      !wasAlreadyAccepted &&
      existingRequest?.requester_id
    ) {
      try {
        const workshopName =
          existingRequest.workshop?.title || "";
        const date = existingRequest.workshop?.starts_at
          ? new Intl.DateTimeFormat("de-DE", {
              timeZone: "Europe/Berlin",
              day: "2-digit",
              month: "2-digit",
              year: "numeric"
            }).format(
              new Date(existingRequest.workshop.starts_at)
            )
          : "";

        const emailResult = await sendPartnerEmail({
          recipientId: existingRequest.requester_id,
          recipientName:
            existingRequest.requester?.display_name ||
            "Tanzfreund/in",
          partnerName:
            existingRequest.recipient?.display_name ||
            "Dein Tanzpartner",
          workshopName,
          date,
          messageType: "accepted"
        });

        if (!emailResult.ok) {
          console.warn(
            "Anfrage wurde angenommen, aber die Bestätigungs-E-Mail konnte nicht gesendet werden."
          );
        }
      } catch (emailError) {
        console.error(
          "Fehler bei der Bestätigungs-E-Mail im Admin-Bereich:",
          emailError
        );
      }
    }

    await loadContactRequests();
  }

