  async function addWorkshop() {
    if (readOnly) {
      alert("Dieser Admin-Zugang ist nur zum Lesen freigegeben.");
      return;
    }
    const title =
      prompt(
        "Name des Workshops:"
      );

    if (!title || !title.trim()) return;

    const levelChoice =
      prompt(
        "Kursniveau (1 = Anfängerkurs, 2 = Mittelstufenkurs, 3 = Fortgeschrittenenkurs):",
        "1"
      ) || "";

    const levelMap = {
      "1": "Anfängerkurs",
      "2": "Mittelstufenkurs",
      "3": "Fortgeschrittenenkurs"
    };

    const level = levelMap[levelChoice.trim()];

    if (!level) {
      alert(
        "Bitte 1, 2 oder 3 für das Kursniveau eingeben."
      );
      return;
    }

    const recurringChoice =
      prompt(
        "Ist dies ein regelmäßiger Dauer-Workshop? (j = ja, n = nein)",
        "n"
      ) || "n";

    const isRecurring =
      recurringChoice.trim().toLowerCase() === "j";

    const recurrenceText = isRecurring
      ? (
          prompt(
            "Wiederholungstext, z.B. „Jeden Samstag“:",
            "Jeden Samstag"
          ) || ""
        ).trim()
      : "";

    if (isRecurring && !recurrenceText) {
      alert("Bitte einen Wiederholungstext eingeben, z.B. „Jeden Samstag“.");
      return;
    }

    const date =
      isRecurring
        ? ""
        : (
            prompt(
              "Datum (TT.MM.JJJJ, optional):"
            ) || ""
          );

    const time =
      prompt(
        "Startzeit (z.B. 14:15):",
        isRecurring ? "14:15" : (date.trim() ? "16:15" : "")
      ) || "";

    const durationInput =
      prompt(
        "Dauer des Workshops in Minuten (z.B. 60):",
        "60"
      ) || "";

    const durationMinutes = durationInput.trim()
      ? Number(durationInput.trim())
      : null;

    if (durationInput.trim() && (!Number.isInteger(durationMinutes) || durationMinutes < 1)) {
      alert("Bitte bei der Dauer eine ganze Zahl in Minuten eingeben, z.B. 60.");
      return;
    }

    const location =
      prompt("Ort:") || "";

    if (!location.trim()) return;

    const costInput =
      prompt(
        "Kosten pro Person (€):",
        "8"
      ) || "";

    const costPerPerson = costInput.trim()
      ? Number(costInput.trim().replace(",", "."))
      : null;

    if (costInput.trim() && (!Number.isFinite(costPerPerson) || costPerPerson < 0)) {
      alert("Bitte bei den Kosten eine gültige Zahl eingeben, z.B. 8 oder 8,00.");
      return;
    }

    const maxPairsInput =
      prompt(
        "Maximale Paaranzahl (optional, z.B. 10):",
        ""
      ) || "";

    const maxPairCount = maxPairsInput.trim()
      ? Number(maxPairsInput.trim())
      : null;

    if (
      maxPairsInput.trim() &&
      (!Number.isInteger(maxPairCount) || maxPairCount < 1)
    ) {
      alert("Bitte eine ganze Zahl ab 1 eingeben oder das Feld leer lassen.");
      return;
    }

    const infoText =
      prompt(
        "Zusätzliche Informationen zum Workshop (optional, max. 500 Zeichen):"
      ) || "";

    if (time.trim() && !/^\d{1,2}:\d{2}$/.test(time.trim())) {
      alert("Bitte die Startzeit im Format HH:MM eingeben oder leer lassen.");
      return;
    }

    if (time.trim()) {
      const [hours, minutes] = time.trim().split(":").map(Number);
      if (hours < 0 || hours > 23 || minutes < 0 || minutes > 59) {
        alert("Bitte eine gültige Startzeit eingeben.");
        return;
      }
    }

    let startsAt = null;

    if (date.trim()) {
      const parts =
        date.trim().split(".");

      if (parts.length !== 3) {
        alert(
          "Bitte das Datum im Format TT.MM.JJJJ eingeben oder leer lassen."
        );
        return;
      }

      const [
        day,
        month,
        year
      ] = parts;

      const selectedTime =
        time.trim() || "16:15";

      if (
        !/^\d{1,2}:\d{2}$/.test(
          selectedTime
        )
      ) {
        alert(
          "Bitte die Startzeit im Format HH:MM eingeben oder leer lassen."
        );
        return;
      }

      const [hours, minutes] =
        selectedTime.split(":").map(Number);

      if (
        hours < 0 ||
        hours > 23 ||
        minutes < 0 ||
        minutes > 59
      ) {
        alert(
          "Bitte eine gültige Startzeit eingeben."
        );
        return;
      }

      const dateCheck =
        new Date(
          Number(year),
          Number(month) - 1,
          Number(day),
          hours,
          minutes
        );

      if (
        dateCheck.getFullYear() !==
          Number(year) ||
        dateCheck.getMonth() !==
          Number(month) - 1 ||
        dateCheck.getDate() !==
          Number(day)
      ) {
        alert(
          "Bitte ein gültiges Datum eingeben."
        );
        return;
      }

      startsAt =
        dateCheck.toISOString();
    }

    const {
      error
    } = await supabase
      .from("workshops")
      .insert({
        title: title.trim(),
        starts_at: startsAt,
        start_time: time.trim() || null,
        duration_minutes: durationMinutes,
        recurrence_text: isRecurring ? recurrenceText : null,
        location: location.trim(),
        cost_per_person: costPerPerson,
        max_pair_count: maxPairCount,
        info_text:
          infoText.trim().slice(0, 500) || null,
        level
      });

    if (error) {
      alert(
        "Fehler beim Anlegen des Workshops: " +
          error.message
      );
      return;
    }

    // Workshop wurde erfolgreich gespeichert.
    // Der Versand erfolgt EINMAL über die Edge Function. Diese lädt
    // die berechtigten Empfänger serverseitig mit Service-Role.
    // Dadurch wird die RLS-Beschränkung des Browsers umgangen.
    let mailInfo = {
      recipientsFound: 0,
      sent: 0,
      failed: 0,
      withoutEmail: 0
    };

    try {
      const formattedDate = startsAt
        ? new Intl.DateTimeFormat("de-DE", {
            timeZone: "Europe/Berlin",
            day: "2-digit",
            month: "2-digit",
            year: "numeric"
          }).format(new Date(startsAt))
        : (isRecurring ? recurrenceText : "");

      const formattedTime = startsAt
        ? new Intl.DateTimeFormat("de-DE", {
            timeZone: "Europe/Berlin",
            hour: "2-digit",
            minute: "2-digit"
          }).format(new Date(startsAt))
        : (isRecurring ? time.trim() : "");

      const { data, error: emailError } =
        await supabase.functions.invoke(
          "send-partner-email",
          {
            body: {
              broadcast: true,
              messageType: "new_workshop",
              workshopName: title.trim(),
              date: formattedDate
                ? `${formattedDate}${formattedTime ? " – " + formattedTime + " Uhr" : ""}`
                : ""
            }
          }
        );

      if (emailError) {
        console.error(
          "Workshop-E-Mail konnte nicht gestartet werden:",
          emailError
        );
        alert(
          "Workshop wurde veröffentlicht.\n\n" +
          "⚠️ Die Workshop-E-Mails konnten nicht gestartet werden.\n" +
          "Fehler: " +
          (emailError.message || "Unbekannter Fehler")
        );
      } else {
        mailInfo = {
          recipientsFound: Number(data?.recipientsFound || 0),
          sent: Number(data?.sent || 0),
          failed: Number(data?.failed || 0),
          withoutEmail: Number(data?.withoutEmail || 0)
        };

        alert(
          "Workshop wurde erfolgreich veröffentlicht.\n\n" +
          "📧 " +
          mailInfo.recipientsFound +
          " Empfänger gefunden\n" +
          "✅ " +
          mailInfo.sent +
          " E-Mails erfolgreich versendet" +
          (mailInfo.failed
            ? "\n⚠️ " + mailInfo.failed + " E-Mails fehlgeschlagen"
            : "") +
          (mailInfo.withoutEmail
            ? "\nℹ️ " + mailInfo.withoutEmail + " Nutzer ohne E-Mail-Adresse"
            : "")
        );
      }
    } catch (emailError) {
      console.error(
        "Fehler beim Start des Workshop-E-Mail-Versands:",
        emailError
      );

      alert(
        "Workshop wurde erfolgreich veröffentlicht.\n\n" +
        "⚠️ Der E-Mail-Versand konnte nicht gestartet werden.\n" +
        "Fehler: " +
        (emailError?.message || "Unbekannter Fehler")
      );
    }

    await loadWorkshops();
  }

  async function copyWorkshop(
    workshop
  ) {
    if (readOnly) {
      alert("Dieser Admin-Zugang ist nur zum Lesen freigegeben.");
      return;
    }

    const defaultDate = workshop.starts_at
      ? (() => {
          const d = new Date(workshop.starts_at);
          return Number.isNaN(d.getTime())
            ? ""
            : `${String(d.getDate()).padStart(2, "0")}.${String(d.getMonth() + 1).padStart(2, "0")}.${d.getFullYear()}`;
        })()
      : "";

    const date = workshop.recurrence_text
      ? (
          prompt(
            "Neues Datum (TT.MM.JJJJ, optional):",
            ""
          ) || ""
        )
      : (
          prompt(
            "Neues Datum (TT.MM.JJJJ, optional):",
            defaultDate
          ) || ""
        );

    const time = prompt(
      "Neue Startzeit (z.B. 16:15, optional):",
      workshop.start_time
        ? String(workshop.start_time).slice(0, 5)
        : workshop.starts_at
          ? (() => {
              const d = new Date(workshop.starts_at);
              return Number.isNaN(d.getTime())
                ? ""
                : `${String(d.getHours()).padStart(2, "0")}:${String(d.getMinutes()).padStart(2, "0")}`;
            })()
          : ""
    ) || "";

    if (time.trim() && !/^\d{1,2}:\d{2}$/.test(time.trim())) {
      alert("Bitte die Startzeit im Format HH:MM eingeben oder leer lassen.");
      return;
    }

    let startsAt = null;

    if (date.trim()) {
      const parts = date.trim().split(".");
      if (parts.length !== 3) {
        alert("Bitte das Datum im Format TT.MM.JJJJ eingeben oder leer lassen.");
        return;
      }

      const [day, month, year] = parts;
      const selectedTime = time.trim() || "16:15";

      if (!/^\d{1,2}:\d{2}$/.test(selectedTime)) {
        alert("Bitte die Startzeit im Format HH:MM eingeben oder leer lassen.");
        return;
      }

      const [hours, minutes] = selectedTime.split(":").map(Number);
      const dateCheck = new Date(
        Number(year),
        Number(month) - 1,
        Number(day),
        hours,
        minutes
      );

      if (
        dateCheck.getFullYear() !== Number(year) ||
        dateCheck.getMonth() !== Number(month) - 1 ||
        dateCheck.getDate() !== Number(day) ||
        hours < 0 || hours > 23 ||
        minutes < 0 || minutes > 59
      ) {
        alert("Bitte ein gültiges Datum und eine gültige Startzeit eingeben.");
        return;
      }

      startsAt = dateCheck.toISOString();
    }

    const newTitle = workshop.title || "";
    const confirmed = confirm(
      `Workshop "${newTitle}" wirklich kopieren?\n\nDer neue Workshop wird ohne Teilnehmer/Anmeldungen angelegt.`
    );

    if (!confirmed) return;

    const { error } = await supabase
      .from("workshops")
      .insert({
        title: newTitle,
        starts_at: startsAt,
        start_time: time.trim() || null,
        duration_minutes: workshop.duration_minutes ?? null,
        recurrence_text: workshop.recurrence_text || null,
        location: workshop.location || null,
        cost_per_person: workshop.cost_per_person ?? null,
        max_pair_count: workshop.max_pair_count ?? null,
        info_text: workshop.info_text || null,
        level: workshop.level || null
      });

    if (error) {
      alert(
        "Fehler beim Kopieren des Workshops: " +
          error.message
      );
      return;
    }

    alert(
      "Workshop wurde kopiert.\n\nDie Teilnehmer und Anmeldungen des ursprünglichen Workshops wurden nicht übernommen."
    );

    await loadWorkshops();
  }

  async function editWorkshop(
    workshop
  ) {
    if (readOnly) {
      alert("Dieser Admin-Zugang ist nur zum Lesen freigegeben.");
      return;
    }
    const title =
      prompt(
        "Name des Workshops:",
        workshop.title || ""
      );

    if (!title || !title.trim()) return;

    const currentLevel =
      workshop.level || "Anfängerkurs";

    const levelChoice =
      prompt(
        "Kursniveau (1 = Anfängerkurs, 2 = Mittelstufenkurs, 3 = Fortgeschrittenenkurs):",
        currentLevel === "Anfängerkurs"
          ? "1"
          : currentLevel === "Mittelstufenkurs"
            ? "2"
            : currentLevel === "Fortgeschrittenenkurs"
              ? "3"
              : ""
      ) || "";

    const levelMap = {
      "1": "Anfängerkurs",
      "2": "Mittelstufenkurs",
      "3": "Fortgeschrittenenkurs"
    };

    const level = levelMap[levelChoice.trim()];

    if (!level) {
      alert(
        "Bitte 1, 2 oder 3 für das Kursniveau eingeben."
      );
      return;
    }

    const recurringChoice =
      prompt(
        "Ist dies ein regelmäßiger Dauer-Workshop? (j = ja, n = nein)",
        workshop.recurrence_text ? "j" : "n"
      ) || (workshop.recurrence_text ? "j" : "n");

    const isRecurring =
      recurringChoice.trim().toLowerCase() === "j";

    const recurrenceText = isRecurring
      ? (
          prompt(
            "Wiederholungstext, z.B. „Jeden Samstag“:",
            workshop.recurrence_text || "Jeden Samstag"
          ) || ""
        ).trim()
      : "";

    if (isRecurring && !recurrenceText) {
      alert("Bitte einen Wiederholungstext eingeben, z.B. „Jeden Samstag“.");
      return;
    }

    let defaultDate = "";

    if (!isRecurring && workshop.starts_at) {
      const dateObj =
        new Date(
          workshop.starts_at
        );

      if (
        !Number.isNaN(
          dateObj.getTime()
        )
      ) {
        defaultDate =
          `${String(
            dateObj.getDate()
          ).padStart(
            2,
            "0"
          )}.${String(
            dateObj.getMonth() + 1
          ).padStart(
            2,
            "0"
          )}.${dateObj.getFullYear()}`;
      }
    }

    const date =
      isRecurring
        ? ""
        : (
            prompt(
              "Datum (TT.MM.JJJJ, optional):",
              defaultDate
            ) || ""
          );

    let defaultTime =
      workshop.start_time
        ? String(workshop.start_time).slice(0, 5)
        : "";

    if (!defaultTime && workshop.starts_at) {
      const dateObj =
        new Date(
          workshop.starts_at
        );

      if (
        !Number.isNaN(
          dateObj.getTime()
        )
      ) {
        defaultTime =
          `${String(
            dateObj.getHours()
          ).padStart(
            2,
            "0"
          )}:${String(
            dateObj.getMinutes()
          ).padStart(
            2,
            "0"
          )}`;
      }
    }

    const time =
      prompt(
        "Startzeit (z.B. 16:15, optional):",
        defaultTime
      ) || "";

    const durationInput =
      prompt(
        "Dauer des Workshops in Minuten (z.B. 60):",
        workshop.duration_minutes != null
          ? String(workshop.duration_minutes)
          : "60"
      ) || "";

    const durationMinutes = durationInput.trim()
      ? Number(durationInput.trim())
      : null;

    if (durationInput.trim() && (!Number.isInteger(durationMinutes) || durationMinutes < 1)) {
      alert("Bitte bei der Dauer eine ganze Zahl in Minuten eingeben, z.B. 60.");
      return;
    }

    const location =
      prompt(
        "Ort:",
        workshop.location || ""
      ) || "";

    if (!location.trim()) return;

    const costInput =
      prompt(
        "Kosten pro Person (€):",
        workshop.cost_per_person != null
          ? String(workshop.cost_per_person).replace(".", ",")
          : "8"
      ) || "";

    const costPerPerson = costInput.trim()
      ? Number(costInput.trim().replace(",", "."))
      : null;

    if (costInput.trim() && (!Number.isFinite(costPerPerson) || costPerPerson < 0)) {
      alert("Bitte bei den Kosten eine gültige Zahl eingeben, z.B. 8 oder 8,00.");
      return;
    }

    const maxPairsInput =
      prompt(
        "Maximale Paaranzahl (optional, z.B. 10):",
        workshop.max_pair_count != null
          ? String(workshop.max_pair_count)
          : ""
      ) || "";

    const maxPairCount = maxPairsInput.trim()
      ? Number(maxPairsInput.trim())
      : null;

    if (
      maxPairsInput.trim() &&
      (!Number.isInteger(maxPairCount) || maxPairCount < 1)
    ) {
      alert("Bitte eine ganze Zahl ab 1 eingeben oder das Feld leer lassen.");
      return;
    }

    const infoText =
      prompt(
        "Zusätzliche Informationen zum Workshop (optional, max. 500 Zeichen):",
        workshop.info_text || ""
      ) || "";

    if (time.trim() && !/^\d{1,2}:\d{2}$/.test(time.trim())) {
      alert("Bitte die Startzeit im Format HH:MM eingeben oder leer lassen.");
      return;
    }

    if (time.trim()) {
      const [hours, minutes] = time.trim().split(":").map(Number);
      if (hours < 0 || hours > 23 || minutes < 0 || minutes > 59) {
        alert("Bitte eine gültige Startzeit eingeben.");
        return;
      }
    }

    let startsAt = null;

    if (date.trim()) {
      const parts =
        date.trim().split(".");

      if (parts.length !== 3) {
        alert(
          "Bitte das Datum im Format TT.MM.JJJJ eingeben oder leer lassen."
        );
        return;
      }

      const [
        day,
        month,
        year
      ] = parts;

      const selectedTime =
        time.trim() || "16:15";

      if (
        !/^\d{1,2}:\d{2}$/.test(
          selectedTime
        )
      ) {
        alert(
          "Bitte die Startzeit im Format HH:MM eingeben oder leer lassen."
        );
        return;
      }

      const [hours, minutes] =
        selectedTime.split(":").map(Number);

      if (
        hours < 0 ||
        hours > 23 ||
        minutes < 0 ||
        minutes > 59
      ) {
        alert(
          "Bitte eine gültige Startzeit eingeben."
        );
        return;
      }

      const dateCheck =
        new Date(
          Number(year),
          Number(month) - 1,
          Number(day),
          hours,
          minutes
        );

      if (
        dateCheck.getFullYear() !==
          Number(year) ||
        dateCheck.getMonth() !==
          Number(month) - 1 ||
        dateCheck.getDate() !==
          Number(day)
      ) {
        alert(
          "Bitte ein gültiges Datum eingeben."
        );
        return;
      }

      startsAt =
        dateCheck.toISOString();
    }

    const { error } =
      await supabase
        .from("workshops")
        .update({
          title: title.trim(),
          starts_at: startsAt,
          start_time: time.trim() || null,
          duration_minutes: durationMinutes,
          recurrence_text: isRecurring ? recurrenceText : null,
          location: location.trim(),
          cost_per_person: costPerPerson,
          max_pair_count: maxPairCount,
          info_text:
            infoText.trim().slice(0, 500) || null,
          level
        })
        .eq(
          "id",
          workshop.id
        );

    if (error) {
      alert(
        "Fehler beim Bearbeiten des Workshops: " +
          error.message
      );
      return;
    }

    alert(
      "Workshop wurde erfolgreich geändert."
    );

    await loadWorkshops();
  }

  async function deleteWorkshop(
    workshop
  ) {
    if (readOnly) {
      alert("Dieser Admin-Zugang ist nur zum Lesen freigegeben.");
      return;
    }
    const confirmed =
      confirm(
        `Workshop "${workshop.title}" wirklich löschen?`
      );

    if (!confirmed) return;

    const { error } =
      await supabase
        .from("workshops")
        .delete()
        .eq(
          "id",
          workshop.id
        );

    if (error) {
      alert(
        "Fehler beim Löschen des Workshops: " +
          error.message
      );
      return;
    }

    alert(
      "Workshop wurde gelöscht."
    );

    await loadWorkshops();
  }

  async function loadParticipants(
    workshopId
  ) {
    // WICHTIG: "Teilnehmer" sind die tatsächlich für den Workshop
    // angemeldeten Personen aus workshop_registrations.
    // workshop_interests enthält dagegen Personen, die einen Tanzpartner
    // suchen. Diese dürfen hier nicht als Teilnehmer erscheinen.
    const [
      { data: registrations, error },
      { data: pairs, error: pairError }
    ] = await Promise.all([
      supabase
        .from("workshop_registrations")
        .select("id,workshop_id,user1_id,user2_id,user1_name,user1_email,user2_name,user2_email,created_at")
        .eq("workshop_id", workshopId)
        .order("created_at", { ascending: true }),

      supabase
        .from("workshop_pairs")
        .select("user1_id,user2_id")
        .eq("workshop_id", workshopId)
    ]);

    if (error) {
      alert(
        "Fehler beim Laden der Teilnehmer: " +
          error.message
      );
      return;
    }

    if (pairError) {
      alert(
        "Fehler beim Laden der Tanzpartnerschaften: " +
          pairError.message
      );
      return;
    }

    const ids = [
      ...new Set([
        ...(registrations || []).flatMap(row => [
          row.user1_id,
          row.user2_id
        ]),
        ...(pairs || []).flatMap(pair => [
          pair.user1_id,
          pair.user2_id
        ])
      ])
    ].filter(Boolean);

    let profiles = [];

    if (ids.length > 0) {
      const {
        data: profileData,
        error: profileError
      } = await supabase
        .from("profiles")
        .select("id,display_name,age,gender")
        .in("id", ids);

      if (profileError) {
        alert(
          "Fehler beim Laden der Profile: " +
            profileError.message
        );
        return;
      }

      profiles = profileData || [];
    }

    const profileMap = Object.fromEntries(
      profiles.map(p => [p.id, p])
    );

    const result = [];
    (registrations || []).forEach(row => {
      [
        { id: row.user1_id, name: row.user1_name, email: row.user1_email },
        { id: row.user2_id, name: row.user2_name, email: row.user2_email }
      ].forEach(person => {
        if (!person.id && !person.name) return;
        result.push({
          user_id: person.id || `${row.id}-${person.name}`,
          profile: person.id
            ? profileMap[person.id] || { display_name: person.name || "Unbekannter Nutzer" }
            : { display_name: person.name || "Unbekannter Nutzer" },
          email: person.email || ""
        });
      });
    });

    // Doppelte Personen vermeiden, falls eine Person in mehreren Datensätzen
    // auftaucht.
    const uniqueResult = [];
    const seen = new Set();
    result.forEach(item => {
      const key = item.user_id || item.profile?.display_name;
      if (seen.has(key)) return;
      seen.add(key);
      uniqueResult.push(item);
    });

    const pairResult =
      (pairs || []).map(pair => ({
        ...pair,
        user1: profileMap[pair.user1_id] || null,
        user2: profileMap[pair.user2_id] || null
      }));

    setParticipants(prev => ({
      ...prev,
      [workshopId]: uniqueResult
    }));

    setWorkshopPairs(prev => ({
      ...prev,
      [workshopId]: pairResult
    }));
  }

  function formatDate(iso) {
    if (!iso) return "";
    return new Intl.DateTimeFormat(
      "de-DE",
      {
        timeZone:
          "Europe/Berlin",
        day: "2-digit",
        month: "2-digit",
        year: "numeric"
      }
    ).format(
      new Date(iso)
    );
  }

  function formatTime(iso) {
    if (!iso) return "";
    return new Intl.DateTimeFormat(
      "de-DE",
      {
        timeZone:
          "Europe/Berlin",
        hour: "2-digit",
        minute: "2-digit",
        hour12: false
      }
    ).format(
      new Date(iso)
    );
  }

